      log('ERROR', `POST /checkout 500 order=${req.body.id} ${e.stack}`);
      return { status: 500, body: { error: 'INTERNAL' } };
    }
  }
  slowQueryWarning(req.path);
  return { status: 404, body: { error: 'NOT_FOUND' } };
}

module.exports = { handle };
