// Regression: POST /checkout returned 500 for prices with thousands separators
// (e.g. "1,299.00"), because parseAmount dereferenced a null regex match.
const assert = require('assert');
const { parseAmount } = require('../src/money');
const { handle } = require('../src/server');

test('parses amounts with thousands separators', () => {
  assert.strictEqual(parseAmount('1,299.00'), 129900);
  assert.strictEqual(parseAmount('2,450.50'), 245050);
  assert.strictEqual(parseAmount('1,005.99'), 100599);
  assert.strictEqual(parseAmount('1,234,567'), 123456700);
});

test('rejects malformed amounts with a clear error', () => {
  for (const bad of ['1,29.00', ',100', '12,', 'abc', '1.234', '']) {
    assert.throws(() => parseAmount(bad), /^Error: Invalid amount: /);
  }
});

test('POST /checkout succeeds for a price with a thousands separator', () => {
  const origLog = console.log;
  console.log = () => {};
  let res;
  try {
    res = handle({
      method: 'POST',
      path: '/checkout',
      body: { id: 'ord_10135', items: [{ sku: 'P-79', price: '2,450.50', qty: 1 }] },
    });
  } finally {
    console.log = origLog;
  }
  assert.strictEqual(res.status, 200);
  assert.deepStrictEqual(res.body, { orderId: 'ord_10135', totalCents: 245050 });
});

